#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>

#define BUFFER_SIZE 5
#define MAX_ITEMS 10

int buffer[BUFFER_SIZE];
int in = 0, out = 0;

sem_t empty_slots;  // initially BUFFER_SIZE
sem_t full_slots;   // initially 0

void* producer(void* arg) {
    for (int i = 0; i < MAX_ITEMS; i++) {
        sem_wait(&empty_slots);
        buffer[in] = i;
        in = (in + 1) % BUFFER_SIZE;
        printf("Producer produced item %d at buffer[%d]\n", i, in - 1);
        sem_post(&full_slots);
    }
    return NULL;
}

void* consumer(void* arg) {
    for (int i = 0; i < MAX_ITEMS; i++) {
        sem_wait(&full_slots);
        int item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        printf("Consumer consumed item %d from buffer[%d]\n", item, out - 1);
        sem_post(&empty_slots);
    }
    return NULL;
}

int main() {
    pthread_t prod_thread, cons_thread;

    sem_init(&empty_slots, 0, BUFFER_SIZE);
    sem_init(&full_slots, 0, 0);

    pthread_create(&prod_thread, NULL, producer, NULL);
    pthread_create(&cons_thread, NULL, consumer, NULL);

    pthread_join(prod_thread, NULL);
    pthread_join(cons_thread, NULL);

    sem_destroy(&empty_slots);
    sem_destroy(&full_slots);

    printf("All items produced and consumed.\n");
    return 0;
}
