#define NUM_READERS 3
#define NUM_WRITERS 2

sem_t read_lock;
sem_t writer_waiting;
sem_t write_lock;
int reader_count = 0;

void* reader_func(void* arg) {
    int id = *(int*)arg;
    printf("Reader %d entering critical section\n", id);
    sem_wait(&read_lock);
    reader_count++;
    if (reader_count == 1) {
        sem_wait(&writer_waiting);
    }
    sem_post(&read_lock);
    printf("Reader %d reading resource\n", id);
    usleep(100000);
    sem_wait(&read_lock);
    reader_count--;
    if (reader_count == 0) {
        sem_post(&writer_waiting);
    }
    sem_post(&read_lock);
    printf("Reader %d exiting critical section\n", id);
    return NULL;
}

void* writer_func(void* arg) {
    int id = *(int*)arg;
    printf("Writer %d entering critical section\n", id);
    sem_wait(&write_lock);
    printf("Writer %d writing resource\n", id);
    usleep(200000);
    sem_post(&write_lock);
    printf("Writer %d exiting critical section\n", id);
    return NULL;
}

int main() {
    pthread_t reader_threads[NUM_READERS];
    pthread_t writer_threads[NUM_WRITERS];
    int reader_ids[NUM_READERS];
    int writer_ids[NUM_WRITERS];

    for (int i = 0; i < NUM_READERS; i++) {
        reader_ids[i] = i;
    }
    for (int i = 0; i < NUM_WRITERS; i++) {
        writer_ids[i] = i;
    }

    sem_init(&read_lock, 0, 1);
    sem_init(&writer_waiting, 0, 0);
    sem_init(&write_lock, 0, 1);

    for (int i = 0; i < NUM_READERS; i++) {
        pthread_create(&reader_threads[i], NULL, reader_func, &reader_ids[i]);
    }
    for (int i = 0; i < NUM_WRITERS; i++) {
        pthread_create(&writer_threads[i], NULL, writer_func, &writer_ids[i]);
    }

    for (int i = 0; i < NUM_READERS; i++) {
        pthread_join(reader_threads[i], NULL);
    }
    for (int i = 0; i < NUM_WRITERS; i++) {
        pthread_join(writer_threads[i], NULL);
    }

    sem_destroy(&read_lock);
    sem_destroy(&writer_waiting);
    sem_destroy(&write_lock);

    return 0;
}
