#include <stdio.h>
#include <pthread.h>
#include <unistd.h>

#define N 5
#define THINK_TIME 1000
#define EAT_TIME 1000

pthread_mutex_t chopsticks[N];

void think(int id) {
    printf("Philosopher %d is thinking.\n", id);
    usleep(THINK_TIME);
}

void eat(int id, int left, int right) {
    printf("Philosopher %d is eating with chopsticks %d and %d.\n", id, left, right);
    usleep(EAT_TIME);
}

void *philosopher(void *arg) {
    int id = *(int *)arg;
    int left = id;
    int right = (id + 1) % N;

    for (int i = 0; i < 100; i++) {
        think(id);
        // Acquire left chopstick first, then right — ensures total lock ordering
        pthread_mutex_lock(&chopsticks[left]);
        pthread_mutex_lock(&chopsticks[right]);
        eat(id, left, right);
        pthread_mutex_unlock(&chopsticks[right]);
        pthread_mutex_unlock(&chopsticks[left]);
    }
    return NULL;
}

int main() {
    pthread_t threads[N];
    int ids[N];

    for (int i = 0; i < N; i++) {
        ids[i] = i;
    }

    for (int i = 0; i < N; i++) {
        pthread_mutex_init(&chopsticks[i], NULL);
    }

    for (int i = 0; i < N; i++) {
        pthread_create(&threads[i], NULL, philosopher, &ids[i]);
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < N; i++) {
        pthread_mutex_destroy(&chopsticks[i]);
    }

    return 0;
}
